-- Phase 9F.4: versioned, Admin-reviewed lesson personalization metadata.
-- This migration never modifies lesson_library and imports all candidates unapproved.
begin;

create table public.lesson_personalization_metadata (
  id uuid primary key default gen_random_uuid(),
  lesson_id uuid not null references public.lesson_library(id) on delete cascade,
  metadata_version integer not null check (metadata_version = 1),
  target_skill_code text,
  mastery_group text,
  skill_stage_code text check (skill_stage_code is null or skill_stage_code in ('beginning','emerging','developing','independent','generalized')),
  prerequisite_skill_codes text[] not null default '{}', assessment_need_tags text[] not null default '{}',
  supported_response_modes text[] not null default '{}',
  min_communication_complexity text, max_communication_complexity text,
  min_independence_level text, max_independence_level text,
  contraindication_tags text[] not null default '{}', material_activity_tags text[] not null default '{}',
  universal_safe_fallback boolean not null default false,
  review_status text not null default 'candidate' check (review_status in ('candidate','needs_review','approved','needs_changes','rejected')),
  candidate_confidence text check (candidate_confidence is null or candidate_confidence in ('HIGH','MEDIUM','LOW','UNKNOWN')),
  candidate_warnings jsonb not null default '[]', candidate_evidence jsonb not null default '{}', candidate_source text not null,
  communication_reviewed boolean not null default false, safety_reviewed boolean not null default false,
  prerequisite_reviewed boolean not null default false, duplicate_reviewed boolean not null default false,
  duplicate_classification text, duplicate_group_id text, validation_errors jsonb not null default '[]',
  review_reason text, reviewed_by uuid references auth.users(id) on delete set null, reviewed_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (lesson_id,metadata_version),
  check (jsonb_typeof(candidate_warnings)='array'), check (jsonb_typeof(validation_errors)='array'),
  check (min_communication_complexity is null or min_communication_complexity in ('beginning_intentional','single_unit','short_combinations','sentences','conversation','unknown')),
  check (max_communication_complexity is null or max_communication_complexity in ('beginning_intentional','single_unit','short_combinations','sentences','conversation','unknown')),
  check (min_independence_level is null or min_independence_level in ('not_started','high_support','learning','mostly_independent','independent','not_current_goal','unknown')),
  check (max_independence_level is null or max_independence_level in ('not_started','high_support','learning','mostly_independent','independent','not_current_goal','unknown')),
  check (supported_response_modes <@ array['spoken_sentences','spoken_phrases','spoken_words','aac','pictures_pecs','signs','gestures_pointing','behavior_body_leading','other']::text[])
);
create index lesson_personalization_metadata_review_idx on public.lesson_personalization_metadata(review_status,candidate_confidence);
create index lesson_personalization_metadata_lesson_idx on public.lesson_personalization_metadata(lesson_id);

create table public.lesson_personalization_metadata_history (
  id uuid primary key default gen_random_uuid(), metadata_id uuid not null references public.lesson_personalization_metadata(id) on delete restrict,
  lesson_id uuid not null references public.lesson_library(id) on delete restrict, metadata_version integer not null,
  previous_review_status text, new_review_status text not null, changed_snapshot jsonb not null,
  reviewer_user_id uuid not null references auth.users(id) on delete restrict, action text not null,
  review_reason text, created_at timestamptz not null default now()
);
create index lesson_personalization_history_metadata_idx on public.lesson_personalization_metadata_history(metadata_id,created_at desc);

alter table public.lesson_personalization_metadata enable row level security;
alter table public.lesson_personalization_metadata_history enable row level security;
revoke all on public.lesson_personalization_metadata from anon,authenticated;
revoke all on public.lesson_personalization_metadata_history from anon,authenticated;
grant select,insert,update on public.lesson_personalization_metadata to authenticated;
grant select on public.lesson_personalization_metadata_history to authenticated;
create policy "App admins manage lesson personalization metadata" on public.lesson_personalization_metadata for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin());
create policy "App admins read lesson personalization history" on public.lesson_personalization_metadata_history for select to authenticated using (public.is_app_admin());

create or replace function public.lesson_personalization_validation_errors(p public.lesson_personalization_metadata)
returns text[] language plpgsql stable set search_path=pg_catalog,public as $$
declare e text[]:='{}'::text[]; comm text[]:=array['beginning_intentional','single_unit','short_combinations','sentences','conversation','unknown']; indep text[]:=array['not_started','high_support','learning','mostly_independent','independent','not_current_goal','unknown'];
begin
 if p.metadata_version<>1 then e:=array_append(e,'Unsupported metadata version.'); end if;
 if p.target_skill_code is null or not (p.target_skill_code=any(array['behavior.frustration','behavior.impulse_control','behavior.transitions_flexibility','communication.answering_questions','communication.conversation','communication.following_directions','communication.intentional_communication','communication.requesting','communication.self_advocacy','communication.speech_clarity','hygiene.general','learning.attention','learning.engagement','learning.executive_function','learning.imitation','learning.matching','learning.memory','learning.problem_solving','learning.sequencing','learning.sorting','learning.task_initiation','learning.visual_attention','learning.working_memory','motor.balance','motor.bilateral','motor.fine','motor.gross','motor.planning','motor.proprioception','motor.writing_readiness','play.cause_effect','play.cooperative','play.functional','play.independent','play.pretend','regulation.calming','regulation.emotional','regulation.general','regulation.identify_emotions','routine.bedtime','routine.household','routine.meals','routine.morning_bedtime','safety.foundational','self_help.dressing','self_help.feeding','social.conflict_resolution','social.friendship','social.joint_attention','social.perspective_taking','social.repair','social.turn_taking','toileting.basic']::text[])) then e:=array_append(e,'Target skill code is missing or unsupported.'); end if;
 if p.mastery_group is null or not (p.mastery_group=any(array['behavior.frustration','behavior.impulse_control','behavior.transitions_flexibility','communication.answering_questions','communication.conversation','communication.following_directions','communication.intentional_communication','communication.requesting','communication.self_advocacy','communication.speech_clarity','hygiene.general','learning.attention','learning.engagement','learning.executive_function','learning.imitation','learning.matching','learning.memory','learning.problem_solving','learning.sequencing','learning.sorting','learning.task_initiation','learning.visual_attention','learning.working_memory','motor.balance','motor.bilateral','motor.fine','motor.gross','motor.planning','motor.proprioception','motor.writing_readiness','play.cause_effect','play.cooperative','play.functional','play.independent','play.pretend','regulation.calming','regulation.emotional','regulation.general','regulation.identify_emotions','routine.bedtime','routine.household','routine.meals','routine.morning_bedtime','safety.foundational','self_help.dressing','self_help.feeding','social.conflict_resolution','social.friendship','social.joint_attention','social.perspective_taking','social.repair','social.turn_taking','toileting.basic']::text[])) then e:=array_append(e,'Mastery group is missing or unsupported.'); end if;
 if exists(select 1 from unnest(p.prerequisite_skill_codes) x where not (x=any(array['behavior.frustration','behavior.impulse_control','behavior.transitions_flexibility','communication.answering_questions','communication.conversation','communication.following_directions','communication.intentional_communication','communication.requesting','communication.self_advocacy','communication.speech_clarity','hygiene.general','learning.attention','learning.engagement','learning.executive_function','learning.imitation','learning.matching','learning.memory','learning.problem_solving','learning.sequencing','learning.sorting','learning.task_initiation','learning.visual_attention','learning.working_memory','motor.balance','motor.bilateral','motor.fine','motor.gross','motor.planning','motor.proprioception','motor.writing_readiness','play.cause_effect','play.cooperative','play.functional','play.independent','play.pretend','regulation.calming','regulation.emotional','regulation.general','regulation.identify_emotions','routine.bedtime','routine.household','routine.meals','routine.morning_bedtime','safety.foundational','self_help.dressing','self_help.feeding','social.conflict_resolution','social.friendship','social.joint_attention','social.perspective_taking','social.repair','social.turn_taking','toileting.basic']::text[]))) then e:=array_append(e,'A prerequisite code is unsupported.'); end if;
 if p.target_skill_code=any(p.prerequisite_skill_codes) then e:=array_append(e,'A target skill cannot be its own prerequisite.'); end if;
 if cardinality(p.prerequisite_skill_codes)<>(select count(distinct x) from unnest(p.prerequisite_skill_codes)x) then e:=array_append(e,'Duplicate prerequisite values are not allowed.'); end if;
 if array_position(comm,p.min_communication_complexity)>array_position(comm,p.max_communication_complexity) then e:=array_append(e,'Communication range is reversed.'); end if;
 if array_position(indep,p.min_independence_level)>array_position(indep,p.max_independence_level) then e:=array_append(e,'Independence range is reversed.'); end if;
 if p.candidate_warnings ? 'COMMUNICATION_REVIEW_REQUIRED' and not p.communication_reviewed then e:=array_append(e,'Communication review is unresolved.'); end if;
 if p.candidate_warnings ? 'SAFETY_REVIEW_REQUIRED' and not p.safety_reviewed then e:=array_append(e,'Safety review is unresolved.'); end if;
 if p.candidate_warnings ? 'DUPLICATE_REVIEW' and not p.duplicate_reviewed then e:=array_append(e,'Duplicate/progression review is unresolved.'); end if;
 if not p.prerequisite_reviewed then e:=array_append(e,'Prerequisite review is unresolved.'); end if;
 if p.universal_safe_fallback and (cardinality(e)>0 or p.candidate_warnings ? 'SAFETY_REVIEW_REQUIRED') then e:=array_append(e,'Universal fallback requires fully resolved, valid safety metadata.'); end if;
 return e;
end;$$;
revoke all on function public.lesson_personalization_validation_errors(public.lesson_personalization_metadata) from public,anon,authenticated;

create or replace function public.log_lesson_personalization_metadata_history() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
begin
 if auth.uid() is null or not public.is_app_admin() then raise exception 'Admin authorization required'; end if;
 if (to_jsonb(old)-'validation_errors'-'updated_at')=(to_jsonb(new)-'validation_errors'-'updated_at') then return new; end if;
 values(new.id,new.lesson_id,new.metadata_version,old.review_status,new.review_status,to_jsonb(new)-'candidate_evidence',auth.uid(),coalesce(current_setting('app.metadata_review_action',true),'update'),new.review_reason);
 return new;
end;$$;
revoke all on function public.log_lesson_personalization_metadata_history() from public,anon,authenticated;
create trigger lesson_personalization_metadata_history_trigger after update on public.lesson_personalization_metadata for each row execute function public.log_lesson_personalization_metadata_history();

create or replace function public.review_lesson_personalization_metadata(p_metadata_id uuid,p_patch jsonb,p_action text,p_review_reason text default null)
returns public.lesson_personalization_metadata language plpgsql security definer set search_path=pg_catalog,public as $$
declare r public.lesson_personalization_metadata; allowed text[]:=array['target_skill_code','mastery_group','skill_stage_code','prerequisite_skill_codes','assessment_need_tags','supported_response_modes','min_communication_complexity','max_communication_complexity','min_independence_level','max_independence_level','contraindication_tags','material_activity_tags','universal_safe_fallback','review_status','communication_reviewed','safety_reviewed','prerequisite_reviewed','duplicate_reviewed','duplicate_classification']; k text; e text[];
begin
 if not public.is_app_admin() then raise exception 'Admin authorization required'; end if;
 for k in select jsonb_object_keys(p_patch) loop if not k=any(allowed) then raise exception 'Unsupported metadata field: %',k; end if; end loop;
 perform set_config('app.metadata_review_action',coalesce(p_action,'review'),true);
 update public.lesson_personalization_metadata m set
 target_skill_code=case when p_patch?'target_skill_code' then p_patch->>'target_skill_code' else m.target_skill_code end,
 mastery_group=case when p_patch?'mastery_group' then p_patch->>'mastery_group' else m.mastery_group end,
 skill_stage_code=case when p_patch?'skill_stage_code' then p_patch->>'skill_stage_code' else m.skill_stage_code end,
 prerequisite_skill_codes=case when p_patch?'prerequisite_skill_codes' then array(select jsonb_array_elements_text(p_patch->'prerequisite_skill_codes')) else m.prerequisite_skill_codes end,
 assessment_need_tags=case when p_patch?'assessment_need_tags' then array(select jsonb_array_elements_text(p_patch->'assessment_need_tags')) else m.assessment_need_tags end,
 supported_response_modes=case when p_patch?'supported_response_modes' then array(select jsonb_array_elements_text(p_patch->'supported_response_modes')) else m.supported_response_modes end,
 min_communication_complexity=case when p_patch?'min_communication_complexity' then p_patch->>'min_communication_complexity' else m.min_communication_complexity end,
 max_communication_complexity=case when p_patch?'max_communication_complexity' then p_patch->>'max_communication_complexity' else m.max_communication_complexity end,
 min_independence_level=case when p_patch?'min_independence_level' then p_patch->>'min_independence_level' else m.min_independence_level end,
 max_independence_level=case when p_patch?'max_independence_level' then p_patch->>'max_independence_level' else m.max_independence_level end,
 contraindication_tags=case when p_patch?'contraindication_tags' then array(select jsonb_array_elements_text(p_patch->'contraindication_tags')) else m.contraindication_tags end,
 material_activity_tags=case when p_patch?'material_activity_tags' then array(select jsonb_array_elements_text(p_patch->'material_activity_tags')) else m.material_activity_tags end,
 universal_safe_fallback=case when p_patch?'universal_safe_fallback' then (p_patch->>'universal_safe_fallback')::boolean else m.universal_safe_fallback end,
 review_status=case when p_patch?'review_status' then p_patch->>'review_status' else m.review_status end,
 communication_reviewed=case when p_patch?'communication_reviewed' then (p_patch->>'communication_reviewed')::boolean else m.communication_reviewed end,
 safety_reviewed=case when p_patch?'safety_reviewed' then (p_patch->>'safety_reviewed')::boolean else m.safety_reviewed end,
 prerequisite_reviewed=case when p_patch?'prerequisite_reviewed' then (p_patch->>'prerequisite_reviewed')::boolean else m.prerequisite_reviewed end,
 duplicate_reviewed=case when p_patch?'duplicate_reviewed' then (p_patch->>'duplicate_reviewed')::boolean else m.duplicate_reviewed end,
 duplicate_classification=case when p_patch?'duplicate_classification' then p_patch->>'duplicate_classification' else m.duplicate_classification end,
 review_reason=p_review_reason,reviewed_by=auth.uid(),reviewed_at=case when p_patch->>'review_status' in ('approved','needs_changes','rejected') then now() else m.reviewed_at end,updated_at=now()
 where m.id=p_metadata_id returning * into r;
 if r.id is null then raise exception 'Metadata record not found'; end if;
 e:=public.lesson_personalization_validation_errors(r);
 if r.review_status='approved' and cardinality(e)>0 then raise exception 'Metadata cannot be approved: %',array_to_string(e,'; '); end if;
 update public.lesson_personalization_metadata set validation_errors=to_jsonb(e) where id=r.id returning * into r;
 return r;
end;$$;
revoke all on function public.review_lesson_personalization_metadata(uuid,jsonb,text,text) from public,anon;
grant execute on function public.review_lesson_personalization_metadata(uuid,jsonb,text,text) to authenticated;

create or replace function public.approve_lesson_personalization_metadata_batch(p_metadata_ids uuid[]) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare mid uuid;r public.lesson_personalization_metadata;e text[];approved int:=0;skipped int:=0;failed int:=0;results jsonb:='[]'::jsonb;
begin
 if not public.is_app_admin() then raise exception 'Admin authorization required'; end if;
 perform set_config('app.metadata_review_action','batch_approve',true);
 foreach mid in array p_metadata_ids loop
  begin
   select * into r from public.lesson_personalization_metadata where id=mid for update;
   if r.id is null then failed:=failed+1;results:=results||jsonb_build_array(jsonb_build_object('id',mid,'result','failed','reasons',array['Not found']));continue;end if;
   e:=public.lesson_personalization_validation_errors(r);
   if cardinality(e)>0 or r.candidate_confidence='LOW' then skipped:=skipped+1;results:=results||jsonb_build_array(jsonb_build_object('id',mid,'result','skipped','reasons',e));continue;end if;
   update public.lesson_personalization_metadata set review_status='approved',validation_errors='[]',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=mid;
   approved:=approved+1;results:=results||jsonb_build_array(jsonb_build_object('id',mid,'result','approved','reasons','[]'::jsonb));
  exception when others then failed:=failed+1;results:=results||jsonb_build_array(jsonb_build_object('id',mid,'result','failed','reasons',array[sqlerrm]));end;
 end loop;
 return jsonb_build_object('approved',approved,'skipped',skipped,'failed',failed,'results',results);
end;$$;
revoke all on function public.approve_lesson_personalization_metadata_batch(uuid[]) from public,anon;
grant execute on function public.approve_lesson_personalization_metadata_batch(uuid[]) to authenticated;

on conflict(lesson_id,metadata_version) do nothing;

comment on table public.lesson_personalization_metadata is 'Versioned lesson targeting metadata; review status is independent of lesson content quality status.';
comment on table public.lesson_personalization_metadata_history is 'Append-only audit history written by the metadata review trigger.';
commit;
